import time


class UesReservationList(object):
    """List of reserved UEs"""

    def __init__(self, reservation_time):
        """
        Basic initialization.
        :param reservation_time:
        """
        self._ues_last_reservations_times = {}
        self.reservation_time = reservation_time

    def update_ue_reservation_time(self, key):
        """

        :param key:
        :return:
        """
        self._ues_last_reservations_times[key] = time.time()

    def is_still_reserved(self, key):
        """

        :param key:
        :return:
        """
        ue_time = time.time() - self._ues_last_reservations_times[key]
        return ue_time < self.reservation_time
